## ---- 01: Kaplan-Meier Estimator  (qmd line 240) --------------------------------------

library(survival)
library(survminer)

loan_panel <- read.csv("data/sample_loan_panel.csv")
fit_km <- survfit(Surv(time, event) ~ sector, data = loan_panel)
ggsurvplot(fit_km, xlab = "Months", ylab = "Survival",
           legend.title = "Sector")


## ---- 02: Cox Proportional-Hazards Model  (qmd line 268) ------------------------------

fit_cox <- coxph(Surv(time, event) ~ coupon_rate + loan_age + sector,
                 data = loan_panel)
summary(fit_cox)


## ---- 03: Time-Varying Covariates  (qmd line 308) -------------------------------------

# Original: one row per loan
# Converted: one row per (loan, covariate interval)
monthly_panel <- read.csv("data/sample_monthly_panel.csv")
loan_monthly_covariates <- with(monthly_panel,
  data.frame(loan_id, month = age, coupon_value = coupon,
             prime_value = prime,
             default_flag = as.integer(event_type == "default")))

# First call establishes each loan's observation window ...
loan_long <- tmerge(data1 = loan_panel, data2 = loan_panel,
                    id = loan_id, tstop = end_month)
# ... then monthly events and time-dependent covariates are layered on
loan_long <- tmerge(data1 = loan_long, data2 = loan_monthly_covariates,
                    id = loan_id,
                    event    = event(month, default_flag),
                    coupon_t = tdc(month, coupon_value),
                    prime_t  = tdc(month, prime_value))

fit_tv <- coxph(Surv(tstart, tstop, event) ~ coupon_t + prime_t, data = loan_long)


## ---- 04: Discrete-Time Hazard via Logit/Cloglog  (qmd line 373) ----------------------

# Discrete-time logit hazard
fit_logit <- glm(event ~ coupon + age + sector + prime_t,
                 family = binomial(link = "logit"),
                 data = loan_monthly_long)


