## ---- 06: Worked Example: Cox Model for Loan-Pool Prepayment  (qmd line 424) ----------

library(survival)

# loan_panel: one row per loan
# Variables: entry_age, exit_age, prepay_event, coupon, sector,
#   balance_log, age_at_start

fit <- coxph(
  Surv(entry_age, exit_age, prepay_event) ~
    coupon + balance_log + factor(sector) +
    pspline(age_at_start, df = 4),   # flexible seasoning
  data = loan_panel
)

summary(fit)
# Output: coefficients, standard errors, hazard ratios, concordance


## ---- 07: Output: coefficients, standard errors, hazard ratios, concordance  (qmd line 450) -

# Schoenfeld residuals
cox.zph(fit)   # global test of proportional hazards

# Concordance
concordance(fit)   # typically 0.65-0.72 for good loan-prepayment models


## ---- 08: Kaplan-Meier with Stratification  (qmd line 482) ----------------------------

library(survival)
library(survminer)

km <- survfit(Surv(loan_age, event) ~ sector, data = loan_panel)
ggsurvplot(km, data = loan_panel, conf.int = TRUE,
           legend.title = "Sector",
           xlab = "Loan age (months)")

# Log-rank test
survdiff(Surv(loan_age, event) ~ sector, data = loan_panel)


## ---- 09: Cox Proportional-Hazards  (qmd line 497) ------------------------------------

fit_cox <- coxph(
  Surv(loan_age, event) ~ coupon + log(balance) + factor(sector) +
    pspline(age_at_start, df = 4),   # seasoning at window entry
  data = loan_panel
)
summary(fit_cox)
exp(coef(fit_cox))    # hazard ratios


## ---- 10: Diagnostic Residuals  (qmd line 509) ----------------------------------------

# Schoenfeld residuals: PH assumption check
library(survminer)
ph_test <- cox.zph(fit_cox)
print(ph_test)
ggcoxzph(ph_test, var = "coupon")

# Martingale residuals: functional form
library(ggplot2)
mart <- residuals(fit_cox, type = "martingale")
ggplot(data.frame(coupon = loan_panel$coupon, residual = mart),
       aes(coupon, residual)) +
  geom_point(alpha = 0.3) +
  geom_smooth(method = "loess", se = FALSE, colour = "red") +
  labs(y = "Martingale residual") +
  theme_minimal()


## ---- 11: Parametric Survival via flexsurv  (qmd line 529) ----------------------------

library(flexsurv)

fit_weibull <- flexsurvreg(
  Surv(loan_age, event) ~ coupon + factor(sector),
  data = loan_panel, dist = "weibull"
)

fit_gengamma <- flexsurvreg(
  Surv(loan_age, event) ~ coupon,
  data = loan_panel, dist = "gengamma"
)
AIC(fit_weibull, fit_gengamma)


## ---- 12: Discrete-Time Hazard via cloglog  (qmd line 546) ----------------------------

library(splines)   # for ns()

# Long-format monthly panel
fit_dt <- glm(prepay_event ~ refi_incentive + log(balance) +
              ns(loan_age, df = 4) + factor(sector),
              family = binomial(link = "cloglog"),
              data = monthly_panel)
summary(fit_dt)

# Predicted monthly SMM
monthly_panel$smm_hat <- predict(fit_dt, type = "response")


## ---- 13: Competing Risks with cmprsk  (qmd line 562) ---------------------------------

library(cmprsk)

# Event types: 0=alive, 1=prepay, 2=default
fit_fg <- crr(ftime = loan_panel$loan_age,
              fstatus = loan_panel$event_type,
              cov1 = model.matrix(~ coupon + balance_log,
                                  loan_panel)[, -1],
              failcode = 1, cencode = 0)
summary(fit_fg)


## ---- 14: Time-Varying Covariates via tmerge  (qmd line 576) --------------------------

monthly_covariates <- with(monthly_panel,
  data.frame(loan_id, month_id = age, prime_value = prime))

# Observation window and terminal event come from the loan-level data ...
loan_long <- tmerge(data1 = loan_panel, data2 = loan_panel,
                    id = loan_id, tstop = end_age,
                    event = event(end_age, prepay_flag))
# ... the monthly prime-rate history enters as a time-dependent covariate
loan_long <- tmerge(data1 = loan_long, data2 = monthly_covariates,
                    id = loan_id,
                    prime_t = tdc(month_id, prime_value))

fit_tv <- coxph(Surv(tstart, tstop, event) ~ prime_t + sector,
                data = loan_long)


